contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 p, uint256 amount) public payable {
        require(p > 0 && amount > 0);
        require(address(this).balance >= amount);
        // Fund C directly through its fallback so it has a nonzero pre-call balance.
        c.fallback{value: p}();
        uint256 before = address(c).balance;
        bool reverted;
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (reverted) {
            // A reverted go() must restore C's balance exactly (atomicity).
            assert(address(c).balance == before && before == p);
        } else {
            // A successful go() must drain C completely, even of earlier funds.
            assert(address(c).balance == 0);
        }
    }
    receive() external payable {}
}

